using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A longest common subsequence in each language - a table, or a function calling itself - whose match moves on in one of the
/// two sequences only, with the change that moves it on in both; the same programs moving on in both, and programs near the
/// mistake but not it, which are left alone. Each row is what the check gave for the
/// program when these were written.
/// </summary>
public class MatchMovesOneTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes, one a line.</summary>
