    [Theory]
    [MemberData(nameof(Mistakes))]
    public void AMatchMovingOnInOneSequenceOnlyIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The programs moving on in both; a table counting how often each item has come up so far; the number of ways one is a
    /// subsequence of the other; every copy of b's items taken out of a; the edit distance; a pattern with *; and the longest
    /// palindromic subsequence.
    /// </summary>
    [Theory]
    [InlineData("Common.java", "public class Common {\n    static String longestCommon(String first, String second) {\n        if (first.isEmpty() || second.isEmpty()) {\n            return \"\";\n        } else if (first.charAt(0) == second.charAt(0)) {\n            return first.charAt(0) + longestCommon(first.substring(1), second.substring(1));\n        } else {\n            String left = longestCommon(first, second.substring(1));\n            String right = longestCommon(first.substring(1), second);\n            return left.length() >= right.length() ? left : right;\n        }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(longestCommon(\"AGGTAB\", \"GTTCCAA\").length());\n    }\n}\n")]
    [InlineData("common.js", "function longestCommon(first, second) {\n  if (first.length === 0 || second.length === 0) return \"\";\n  if (first[0] === second[0]) return first[0] + longestCommon(first.slice(1), second.slice(1));\n  const left = longestCommon(first, second.slice(1));\n  const right = longestCommon(first.slice(1), second);\n  return left.length >= right.length ? left : right;\n}\n\nconsole.log(longestCommon(\"AGGTAB\", \"GTTCCAA\").length);\n")]
    [InlineData("common.py", "def longest_common(first, second):\n    if not first or not second:\n        return \"\"\n    if first[0] == second[0]:\n        return first[0] + longest_common(first[1:], second[1:])\n    left = longest_common(first, second[1:])\n    right = longest_common(first[1:], second)\n    return left if len(left) >= len(right) else right\n\n\nprint(len(longest_common(\"AGGTAB\", \"GTTCCAA\")))\n")]
